class ShelterPet:
    def __init__(self, name, species, age):
        if age < 0:
            raise ValueError("age cannot be negative")

        self.name = name
        self.species = species
        self.age = age
        self.adopted = False

    def is_available(self):
        return not self.adopted

    def adoption_label(self):
        return self.name

    def mark_adopted(self):
        # BUG: this reports success but does not update adopted state.
        return True

